function registerPinsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "GET", path_prefix * "/pins/analytics", OpenAPI.Servers.middleware(impl, multi_pins_analytics_read, multi_pins_analytics_validate, multi_pins_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/pins/{pin_id}/analytics", OpenAPI.Servers.middleware(impl, pins_analytics_read, pins_analytics_validate, pins_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/pins", OpenAPI.Servers.middleware(impl, pins_create_read, pins_create_validate, pins_create_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/pins/{pin_id}", OpenAPI.Servers.middleware(impl, pins_delete_read, pins_delete_validate, pins_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/pins/{pin_id}", OpenAPI.Servers.middleware(impl, pins_get_read, pins_get_validate, pins_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/pins", OpenAPI.Servers.middleware(impl, pins_list_read, pins_list_validate, pins_list_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/pins/{pin_id}/save", OpenAPI.Servers.middleware(impl, pins_save_read, pins_save_validate, pins_save_invoke; optional_middlewares...))
    HTTP.register!(router, "PATCH", path_prefix * "/pins/{pin_id}", OpenAPI.Servers.middleware(impl, pins_update_read, pins_update_validate, pins_update_invoke; optional_middlewares...))
    return router
end
